import {win32,posix} from 'node:path';
const usage=[];export function readUsage(){return structuredClone(usage)};
export async function createIndex({baseDirectory,flavor}){usage.push({method:'createIndex',baseDirectory,flavor});const api=flavor==='win32'?win32:posix;const records=[];return {async add({relativePath,content}){if(!(content instanceof Uint8Array))throw new TypeError('content must be bytes');await Promise.resolve();usage.push({method:'add',relativePath,content:[...content]});records.push({location:api.join(baseDirectory,relativePath),byteLength:content.byteLength})},async close(){usage.push({method:'close'});return {format:2,records:records.map(record=>({...record}))}}}}
